from abc import ABC, abstractmethod

class MySQLDatabase:
    def __init__(self):
        self.user_data = {}

class UserOperation(ABC):
    @abstractmethod
    def execute(self, database: MySQLDatabase):
        pass

class AddUserOperation(UserOperation):
    def __init__(self, id: int, name: str):
        self.id = id
        self.name = name

    def execute(self, database: MySQLDatabase):
        user_data = database.user_data
        if self.id not in user_data:
            user_data[self.id] = self.name
            return "User added successfully."
        return "User ID already exists."

# Similar classes can be added for delete, update, etc.

class UserService:
    def __init__(self):
        self.database = MySQLDatabase()

    def execute_operation(self, operation: UserOperation):
        return operation.execute(self.database)
